WITH o AS (SELECT o.order_id, CAST(MAKEDATE(YEAR(o.order_at), 1) + INTERVAL (QUARTER(o.order_at) - 1) QUARTER AS DATE) AS qtr FROM orders o WHERE NOT o.is_deleted AND o.status NOT IN ('cancelled', 'canceled', 'payment_failed') AND CAST(o.order_at AS DATE) BETWEEN DATE '2024-07-01' AND DATE '2025-06-30'), cap AS (SELECT o.qtr, SUM(p.amount_bdt) AS c FROM payments p JOIN o ON o.order_id = p.order_id WHERE p.status = 'captured' GROUP BY 1), ref AS (SELECT o.qtr, SUM(r.amount_bdt) AS rf FROM refunds r JOIN o ON o.order_id = r.order_id GROUP BY 1) SELECT cap.qtr AS quarter, cap.c - COALESCE(ref.rf, 0) AS net_revenue FROM cap LEFT JOIN ref ON ref.qtr = cap.qtr ORDER BY 1
